=== FILE: axil_timer.v ===
// axil_timer.v
// AXI4-Lite subordinate: 32-bit down-counting timer, one-shot and periodic
// modes, level interrupt. Implements interface_spec.md following
// microarchitecture.md (channels as in the AXI4-Lite register block).
`default_nettype none

module axil_timer #(
    parameter ADDR_WIDTH = 4
) (
    input  wire                  aclk,
    input  wire                  aresetn,
    input  wire [ADDR_WIDTH-1:0] s_axil_awaddr,
    input  wire                  s_axil_awvalid,
    output wire                  s_axil_awready,
    input  wire [31:0]           s_axil_wdata,
    input  wire [3:0]            s_axil_wstrb,
    input  wire                  s_axil_wvalid,
    output wire                  s_axil_wready,
    output wire [1:0]            s_axil_bresp,
    output wire                  s_axil_bvalid,
    input  wire                  s_axil_bready,
    input  wire [ADDR_WIDTH-1:0] s_axil_araddr,
    input  wire                  s_axil_arvalid,
    output wire                  s_axil_arready,
    output wire [31:0]           s_axil_rdata,
    output wire [1:0]            s_axil_rresp,
    output wire                  s_axil_rvalid,
    input  wire                  s_axil_rready,
    output wire                  irq
);

  localparam [1:0] RESP_OKAY   = 2'b00;
  localparam [1:0] RESP_SLVERR = 2'b10;

  localparam [1:0] IDX_CTRL   = 2'd0;
  localparam [1:0] IDX_LOAD   = 2'd1;
  localparam [1:0] IDX_COUNT  = 2'd2;
  localparam [1:0] IDX_STATUS = 2'd3;

  // ------------------------------------------------------------------
  // State
  // ------------------------------------------------------------------
  // Channel state
  reg                  aw_held;
  reg [ADDR_WIDTH-1:0] aw_addr_q;
  reg                  w_held;
  reg [31:0]           w_data_q;
  reg [3:0]            w_strb_q;
  reg                  bvalid_q;
  reg [1:0]            bresp_q;
  reg                  rvalid_q;
  reg [31:0]           rdata_q;
  reg [1:0]            rresp_q;

  // Timer state
  reg                  en;
  reg                  ie;
  reg                  mode;
  reg                  expired;
  reg [31:0]           load_q;
  reg [31:0]           count_q;

  // ------------------------------------------------------------------
  // Outputs (all driven from flops)
  // ------------------------------------------------------------------
  assign s_axil_awready = !aw_held && !bvalid_q;
  assign s_axil_wready  = !w_held && !bvalid_q;
  assign s_axil_bvalid  = bvalid_q;
  assign s_axil_bresp   = bresp_q;
  assign s_axil_arready = !rvalid_q;
  assign s_axil_rvalid  = rvalid_q;
  assign s_axil_rdata   = rdata_q;
  assign s_axil_rresp   = rresp_q;
  assign irq            = expired && ie;

  // ------------------------------------------------------------------
  // Write path
  // ------------------------------------------------------------------
  wire aw_hs    = s_axil_awvalid && s_axil_awready;
  wire w_hs     = s_axil_wvalid && s_axil_wready;
  wire aw_have  = aw_held || aw_hs;
  wire w_have   = w_held || w_hs;
  wire do_write = aw_have && w_have;

  wire [ADDR_WIDTH-1:0] wr_addr = aw_held ? aw_addr_q : s_axil_awaddr;
  wire [31:0]           wr_data = w_held ? w_data_q : s_axil_wdata;
  wire [3:0]            wr_strb = w_held ? w_strb_q : s_axil_wstrb;

  wire       wr_mapped  = (wr_addr[1:0] == 2'b00) &&
                          ((wr_addr >> 4) == {ADDR_WIDTH{1'b0}});
  wire [1:0] wr_idx     = wr_addr[3:2];
  wire       wr_okay    = wr_mapped && (wr_idx != IDX_COUNT);
  wire       ctrl_wr    = do_write && wr_mapped && (wr_idx == IDX_CTRL) && wr_strb[0];
  wire       load_wr    = do_write && wr_mapped && (wr_idx == IDX_LOAD);
  wire       status_clr = do_write && wr_mapped && (wr_idx == IDX_STATUS) &&
                          wr_strb[0] && wr_data[0];

  // ------------------------------------------------------------------
  // Read path
  // ------------------------------------------------------------------
  wire       ar_hs     = s_axil_arvalid && s_axil_arready;
  wire       rd_mapped = (s_axil_araddr[1:0] == 2'b00) &&
                         ((s_axil_araddr >> 4) == {ADDR_WIDTH{1'b0}});
  wire [1:0] rd_idx    = s_axil_araddr[3:2];

  reg [31:0] rd_val;
  always @(*) begin
    rd_val = 32'd0;
    if (rd_mapped) begin
      case (rd_idx)
        IDX_CTRL:   rd_val = {29'd0, mode, ie, en};
        IDX_LOAD:   rd_val = load_q;
        IDX_COUNT:  rd_val = count_q;
        IDX_STATUS: rd_val = {31'd0, expired};
        default:    rd_val = 32'd0;
      endcase
    end
  end

  // ------------------------------------------------------------------
  // Timer
  // ------------------------------------------------------------------
  // Last cycle of a count; a count of 0 is treated like 1.
  wire count_end = en && (count_q <= 32'd1);

  // ------------------------------------------------------------------
  // Registers. Order inside the block follows microarchitecture.md
  // section 2, so later assignments win: count step, expired
  // (clear then set), CTRL write, LOAD write.
  // ------------------------------------------------------------------
  always @(posedge aclk) begin
    if (!aresetn) begin
      aw_held   <= 1'b0;
      aw_addr_q <= {ADDR_WIDTH{1'b0}};
      w_held    <= 1'b0;
      w_data_q  <= 32'd0;
      w_strb_q  <= 4'd0;
      bvalid_q  <= 1'b0;
      bresp_q   <= RESP_OKAY;
      rvalid_q  <= 1'b0;
      rdata_q   <= 32'd0;
      rresp_q   <= RESP_OKAY;
      en        <= 1'b0;
      ie        <= 1'b0;
      mode      <= 1'b0;
      expired   <= 1'b0;
      load_q    <= 32'd0;
      count_q   <= 32'd0;
    end else begin
      // Write address / data holding
      if (do_write) begin
        aw_held <= 1'b0;
        w_held  <= 1'b0;
      end else begin
        if (aw_hs) begin
          aw_held   <= 1'b1;
          aw_addr_q <= s_axil_awaddr;
        end
        if (w_hs) begin
          w_held   <= 1'b1;
          w_data_q <= s_axil_wdata;
          w_strb_q <= s_axil_wstrb;
        end
      end

      // Write response
      if (do_write) begin
        bvalid_q <= 1'b1;
        bresp_q  <= wr_okay ? RESP_OKAY : RESP_SLVERR;
      end else if (bvalid_q && s_axil_bready) begin
        bvalid_q <= 1'b0;
      end

      // Read response
      if (ar_hs) begin
        rvalid_q <= 1'b1;
        rdata_q  <= rd_val;
        rresp_q  <= rd_mapped ? RESP_OKAY : RESP_SLVERR;
      end else if (rvalid_q && s_axil_rready) begin
        rvalid_q <= 1'b0;
      end

      // 1. Count step
      if (count_end) begin
        if (mode) begin
          count_q <= load_q;
        end else begin
          count_q <= 32'd0;
          en      <= 1'b0;
        end
      end else if (en) begin
        count_q <= count_q - 32'd1;
      end

      // 2. Expired: clear, then set (a count end beats a clear)
      if (status_clr) begin
        expired <= 1'b0;
      end
      if (count_end) begin
        expired <= 1'b1;
      end

      // 3. CTRL write wins for en and count
      if (ctrl_wr) begin
        ie   <= wr_data[1];
        mode <= wr_data[2];
        if (wr_data[0]) begin
          en      <= 1'b1;
          count_q <= load_q;
        end else begin
          en <= 1'b0;
        end
      end

      // 4. LOAD write, byte merge
      if (load_wr) begin
        if (wr_strb[0]) load_q[7:0]   <= wr_data[7:0];
        if (wr_strb[1]) load_q[15:8]  <= wr_data[15:8];
        if (wr_strb[2]) load_q[23:16] <= wr_data[23:16];
        if (wr_strb[3]) load_q[31:24] <= wr_data[31:24];
      end
    end
  end

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: axil_timer_tb.v ===
// axil_timer_tb.v
// Self-checking directed testbench for axil_timer (interface_spec.md
// section 8). Two instances, ADDR_WIDTH 8 (checked) and ADDR_WIDTH 4
// (compared cycle by cycle against the first on mapped traffic).
// Stimulus changes on the falling edge; outputs are sampled on the
// falling edge, where they are stable.
`timescale 1ns/1ps
`default_nettype none

`define CHECK(C_, M_) \
  begin \
    if (C_) passed = passed + 1; \
    else begin failed = failed + 1; $error("%0s", M_); end \
  end

`define CHECKEQ(G_, X_, M_) \
  begin \
    if ((G_) === (X_)) passed = passed + 1; \
    else begin failed = failed + 1; $error("%0s: got 0x%0h expected 0x%0h", M_, G_, X_); end \
  end

module axil_timer_tb;

  localparam [7:0] A_CTRL   = 8'h00;
  localparam [7:0] A_LOAD   = 8'h04;
  localparam [7:0] A_COUNT  = 8'h08;
  localparam [7:0] A_STATUS = 8'h0C;
  localparam [1:0] OKAY     = 2'b00;
  localparam [1:0] SLVERR   = 2'b10;

  // ------------------------------------------------------------------
  // Clock, stimulus
  // ------------------------------------------------------------------
  reg aclk = 1'b0;
  always #5 aclk = ~aclk;

  reg        aresetn = 1'b0;
  reg [7:0]  awaddr  = 8'h00;
  reg        awvalid = 1'b0;
  reg [31:0] wdata   = 32'h0;
  reg [3:0]  wstrb   = 4'h0;
  reg        wvalid  = 1'b0;
  reg        bready  = 1'b0;
  reg [7:0]  araddr  = 8'h00;
  reg        arvalid = 1'b0;
  reg        rready  = 1'b0;

  // ------------------------------------------------------------------
  // DUTs
  // ------------------------------------------------------------------
  wire        awready8, wready8, bvalid8, arready8, rvalid8, irq8;
  wire [1:0]  bresp8, rresp8;
  wire [31:0] rdata8;
  wire        awready4, wready4, bvalid4, arready4, rvalid4, irq4;
  wire [1:0]  bresp4, rresp4;
  wire [31:0] rdata4;

  axil_timer #(.ADDR_WIDTH(8)) dut8 (
    .aclk(aclk), .aresetn(aresetn),
    .s_axil_awaddr(awaddr), .s_axil_awvalid(awvalid), .s_axil_awready(awready8),
    .s_axil_wdata(wdata), .s_axil_wstrb(wstrb), .s_axil_wvalid(wvalid), .s_axil_wready(wready8),
    .s_axil_bresp(bresp8), .s_axil_bvalid(bvalid8), .s_axil_bready(bready),
    .s_axil_araddr(araddr), .s_axil_arvalid(arvalid), .s_axil_arready(arready8),
    .s_axil_rdata(rdata8), .s_axil_rresp(rresp8), .s_axil_rvalid(rvalid8), .s_axil_rready(rready),
    .irq(irq8)
  );

  axil_timer #(.ADDR_WIDTH(4)) dut4 (
    .aclk(aclk), .aresetn(aresetn),
    .s_axil_awaddr(awaddr[3:0]), .s_axil_awvalid(awvalid), .s_axil_awready(awready4),
    .s_axil_wdata(wdata), .s_axil_wstrb(wstrb), .s_axil_wvalid(wvalid), .s_axil_wready(wready4),
    .s_axil_bresp(bresp4), .s_axil_bvalid(bvalid4), .s_axil_bready(bready),
    .s_axil_araddr(araddr[3:0]), .s_axil_arvalid(arvalid), .s_axil_arready(arready4),
    .s_axil_rdata(rdata4), .s_axil_rresp(rresp4), .s_axil_rvalid(rvalid4), .s_axil_rready(rready),
    .irq(irq4)
  );

  // ------------------------------------------------------------------
  // Bookkeeping
  // ------------------------------------------------------------------
  integer passed = 0;
  integer failed = 0;
  integer cyc = 0;              // number of rising edges so far
  always @(posedge aclk) cyc <= cyc + 1;

  reg [8*64-1:0] nonce = {512{1'b0}};
  integer got_nonce;

  integer last_wr_edge = 0;     // edge on which the last write took effect
  integer last_rd_edge = 0;     // edge on which the last read was accepted
  reg     irq_at_wr = 1'b0;     // irq right after the last write's edge
  reg [31:0] rd_data = 32'h0;
  reg [1:0]  rd_resp = 2'b00;

  integer e0, e1, k, rises0;
  reg [31:0] m_load, exp_v, frozen;

  // ------------------------------------------------------------------
  // Monitor (samples pre-edge values on every rising edge)
  // ------------------------------------------------------------------
  reg        cmp_en = 1'b1;
  reg        seen_reset = 1'b0;
  reg        p_mon = 1'b0;
  reg        p_bvalid = 1'b0;
  reg        p_bready = 1'b0;
  reg [1:0]  p_bresp = 2'b00;
  reg        p_rvalid = 1'b0;
  reg        p_rready = 1'b0;
  reg [1:0]  p_rresp = 2'b00;
  reg [31:0] p_rdata = 32'h0;
  reg        p_irq = 1'b0;
  integer    mon_pass = 0;
  integer    mon_failed = 0;
  integer    cmp_fail = 0;
  integer    irq_rises = 0;

  always @(posedge aclk) begin
    if (p_mon) begin
      if (p_bvalid && !p_bready) begin
        if (bvalid8 && (bresp8 == p_bresp)) mon_pass = mon_pass + 1;
        else begin mon_failed = mon_failed + 1; $error("B channel changed while stalled"); end
      end
      if (p_rvalid && !p_rready) begin
        if (rvalid8 && (rdata8 == p_rdata) && (rresp8 == p_rresp)) mon_pass = mon_pass + 1;
        else begin mon_failed = mon_failed + 1; $error("R channel changed while stalled"); end
      end
      if (bvalid8 && (awready8 || wready8)) begin
        mon_failed = mon_failed + 1; $error("write channel ready while a response waits");
      end
      if (rvalid8 && arready8) begin
        mon_failed = mon_failed + 1; $error("ARREADY high while a read response waits");
      end
      if (irq8 && !p_irq) irq_rises = irq_rises + 1;
    end
    if (seen_reset && cmp_en &&
        ({awready4, wready4, bvalid4, bresp4, arready4, rvalid4, rresp4, rdata4, irq4} !==
         {awready8, wready8, bvalid8, bresp8, arready8, rvalid8, rresp8, rdata8, irq8})) begin
      cmp_fail = cmp_fail + 1;
      $error("ADDR_WIDTH 4 and ADDR_WIDTH 8 instances disagree");
    end
    seen_reset <= seen_reset || !aresetn;
    p_mon    <= aresetn;
    p_bvalid <= bvalid8;
    p_bready <= bready;
    p_bresp  <= bresp8;
    p_rvalid <= rvalid8;
    p_rready <= rready;
    p_rresp  <= rresp8;
    p_rdata  <= rdata8;
    p_irq    <= irq8;
  end

  // ------------------------------------------------------------------
  // Model helper
  // ------------------------------------------------------------------
  function [31:0] merge;
    input [31:0] old_v;
    input [31:0] new_v;
    input [3:0]  s;
    begin
      merge = {s[3] ? new_v[31:24] : old_v[31:24],
               s[2] ? new_v[23:16] : old_v[23:16],
               s[1] ? new_v[15:8]  : old_v[15:8],
               s[0] ? new_v[7:0]   : old_v[7:0]};
    end
  endfunction

  // ------------------------------------------------------------------
  // Tasks (all called right after a falling edge, all return right
  // after a falling edge)
  // ------------------------------------------------------------------
  task apply_reset;
    begin
      aresetn = 1'b0;
      awvalid = 1'b0;
      wvalid  = 1'b0;
      arvalid = 1'b0;
      bready  = 1'b0;
      rready  = 1'b0;
      repeat (3) @(negedge aclk);
      aresetn = 1'b1;
      @(negedge aclk);
    end
  endtask

  // order: 0 AW and W together, 1 AW first, 2 W first
  task do_write;
    input [7:0]  addr;
    input [31:0] data;
    input [3:0]  strb;
    input integer order;
    input integer bdelay;
    input [1:0]  exp_resp;
    reg aw_done, w_done, fire_aw, fire_w;
    reg [1:0] resp0;
    integer gap, t;
    begin
      awaddr  = addr;
      wdata   = data;
      wstrb   = strb;
      aw_done = 1'b0;
      w_done  = 1'b0;
      gap     = 0;
      t       = 0;
      awvalid = (order != 2) ? 1'b1 : 1'b0;
      wvalid  = (order != 1) ? 1'b1 : 1'b0;
      while (!(aw_done && w_done) && (t < 64)) begin
        `CHECK(!bvalid8, "BVALID low before the write completes")
        fire_aw = awvalid && awready8;
        fire_w  = wvalid && wready8;
        if ((aw_done || fire_aw) && (w_done || fire_w)) last_wr_edge = cyc + 1;
        @(negedge aclk);
        t = t + 1;
        if (fire_aw) begin
          aw_done = 1'b1;
          awvalid = 1'b0;
          if (!w_done && !fire_w) awaddr = ~addr;   // the held copy must be used
        end
        if (fire_w) begin
          w_done = 1'b1;
          wvalid = 1'b0;
          if (!aw_done) begin wdata = ~data; wstrb = ~strb; end
        end
        if (aw_done && !w_done) `CHECK(!awready8, "AWREADY low while an address is held")
        if (w_done && !aw_done) `CHECK(!wready8, "WREADY low while data is held")
        if ((order == 1) && aw_done && !w_done && !wvalid) begin
          gap = gap + 1;
          if (gap >= 2) wvalid = 1'b1;
        end
        if ((order == 2) && w_done && !aw_done && !awvalid) begin
          gap = gap + 1;
          if (gap >= 2) awvalid = 1'b1;
        end
      end
      `CHECK(aw_done && w_done, "write handshakes complete")
      `CHECK(bvalid8, "BVALID high on the edge after the write completes")
      `CHECKEQ(bresp8, exp_resp, "BRESP")
      if (bresp8 !== exp_resp) $display("  (write to address 0x%02h)", addr);
      `CHECK(!awready8 && !wready8, "no write accepted while BVALID is high")
      irq_at_wr = irq8;
      resp0 = bresp8;
      repeat (bdelay) begin
        @(negedge aclk);
        `CHECK(bvalid8 && (bresp8 == resp0), "B held stable under backpressure")
      end
      bready = 1'b1;
      @(negedge aclk);
      bready = 1'b0;
      `CHECK(!bvalid8, "BVALID drops after the B handshake")
    end
  endtask

  task wr;
    input [7:0]  addr;
    input [31:0] data;
    begin
      do_write(addr, data, 4'hF, 0, 0, OKAY);
    end
  endtask

  task do_read;
    input [7:0] addr;
    input integer rdelay;
    integer t;
    begin
      `CHECK(!rvalid8, "RVALID low before the read")
      araddr  = addr;
      arvalid = 1'b1;
      t = 0;
      while (!arready8 && (t < 64)) begin
        @(negedge aclk);
        t = t + 1;
      end
      `CHECK(arready8, "ARREADY seen for the read")
      last_rd_edge = cyc + 1;
      @(negedge aclk);
      arvalid = 1'b0;
      `CHECK(rvalid8, "RVALID high on the edge after the address is accepted")
      `CHECK(!arready8, "ARREADY low while RVALID is high")
      rd_data = rdata8;
      rd_resp = rresp8;
      repeat (rdelay) begin
        @(negedge aclk);
        `CHECK(rvalid8 && (rdata8 == rd_data) && (rresp8 == rd_resp), "R held stable under backpressure")
      end
      rready = 1'b1;
      @(negedge aclk);
      rready = 1'b0;
      `CHECK(!rvalid8, "RVALID drops after the R handshake")
    end
  endtask

  task rd_expect;
    input [7:0]  addr;
    input [31:0] exp_data;
    input [1:0]  exp_resp;
    begin
      do_read(addr, 0);
      if ((rd_data !== exp_data) || (rd_resp !== exp_resp))
        $display("  (read of address 0x%02h)", addr);
      `CHECKEQ(rd_data, exp_data, "read data")
      `CHECKEQ(rd_resp, exp_resp, "read response")
    end
  endtask

  task wait_until;
    input integer c;
    begin
      `CHECK(cyc <= c, "scheduled cycle is not in the past")
      while (cyc < c) @(negedge aclk);
    end
  endtask

  // irq must be low after every edge before e and high after edge e
  task expect_irq_edge;
    input integer e;
    begin
      `CHECK(cyc <= e, "irq window starts no later than the expected edge")
      while (cyc < e) begin
        `CHECK(!irq8, "irq low before the count ends")
        @(negedge aclk);
      end
      `CHECK(irq8, "irq high right after the edge the count ends")
    end
  endtask

  // ------------------------------------------------------------------
  // Watchdog
  // ------------------------------------------------------------------
  initial begin
    #(2000000);
    $error("watchdog timeout");
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed + 1);
    $finish;
  end

  // ------------------------------------------------------------------
  // Test sequence
  // ------------------------------------------------------------------
  initial begin
    got_nonce = $value$plusargs("nirmaan_nonce=%s", nonce);
    if (got_nonce == 0) $display("note: no +nirmaan_nonce given");

    aresetn = 1'b0;
    cmp_en  = 1'b1;
    repeat (4) @(negedge aclk);
    aresetn = 1'b1;
    @(negedge aclk);

    // ---------------- reset values ----------------
    $display("--- reset values");
    `CHECK(awready8 && wready8 && arready8, "ready signals high after reset")
    `CHECK(!bvalid8 && !rvalid8, "no response pending after reset")
    `CHECK(!irq8, "irq low after reset")
    rd_expect(A_CTRL, 32'h0, OKAY);
    rd_expect(A_LOAD, 32'h0, OKAY);
    rd_expect(A_COUNT, 32'h0, OKAY);
    rd_expect(A_STATUS, 32'h0, OKAY);

    // ---------------- LOAD strobes, channel orders, backpressure ----
    $display("--- LOAD strobes and channel orders");
    m_load = 32'h0;
    do_write(A_LOAD, 32'h11223344, 4'b1111, 0, 0, OKAY);
    m_load = merge(m_load, 32'h11223344, 4'b1111);
    rd_expect(A_LOAD, m_load, OKAY);
    do_write(A_LOAD, 32'hAABBCCDD, 4'b0101, 0, 0, OKAY);
    m_load = merge(m_load, 32'hAABBCCDD, 4'b0101);
    rd_expect(A_LOAD, m_load, OKAY);
    `CHECKEQ(m_load, 32'h11BB33DD, "model byte merge")
    do_write(A_LOAD, 32'h55667788, 4'b1010, 1, 3, OKAY);
    m_load = merge(m_load, 32'h55667788, 4'b1010);
    rd_expect(A_LOAD, m_load, OKAY);
    `CHECKEQ(m_load, 32'h55BB77DD, "model byte merge")
    do_write(A_LOAD, 32'h99999999, 4'b0000, 2, 2, OKAY);
    rd_expect(A_LOAD, m_load, OKAY);
    do_write(A_LOAD, 32'hCAFEF00D, 4'b1111, 2, 0, OKAY);
    m_load = 32'hCAFEF00D;
    do_read(A_LOAD, 4);
    `CHECKEQ(rd_data, m_load, "LOAD read under R backpressure")
    `CHECKEQ(rd_resp, OKAY, "LOAD read response")

    // ---------------- CTRL without wstrb[0] ----------------
    $display("--- CTRL write without wstrb[0]");
    do_write(A_CTRL, 32'h00000007, 4'b1110, 0, 0, OKAY);
    rd_expect(A_CTRL, 32'h0, OKAY);
    repeat (3) @(negedge aclk);
    rd_expect(A_COUNT, 32'h0, OKAY);

    // ---------------- COUNT is read only ----------------
    $display("--- COUNT read only");
    do_write(A_COUNT, 32'h12345678, 4'b1111, 1, 1, SLVERR);
    rd_expect(A_COUNT, 32'h0, OKAY);
    rd_expect(A_LOAD, m_load, OKAY);
    rd_expect(A_CTRL, 32'h0, OKAY);

    // ---------------- unaligned addresses ----------------
    $display("--- unaligned addresses");
    do_write(8'h05, 32'h00000000, 4'b1111, 0, 0, SLVERR);
    rd_expect(A_LOAD, m_load, OKAY);
    do_write(8'h01, 32'h00000003, 4'b1111, 2, 0, SLVERR);
    rd_expect(A_CTRL, 32'h0, OKAY);
    do_write(8'h0E, 32'h00000001, 4'b1111, 1, 0, SLVERR);
    do_write(8'h03, 32'hFFFFFFFF, 4'b1111, 0, 0, SLVERR);
    rd_expect(A_CTRL, 32'h0, OKAY);
    rd_expect(8'h01, 32'h0, SLVERR);
    rd_expect(8'h06, 32'h0, SLVERR);
    rd_expect(8'h0A, 32'h0, SLVERR);
    rd_expect(8'h0F, 32'h0, SLVERR);

    // ---------------- one-shot timing ----------------
    $display("--- one-shot");
    wr(A_LOAD, 32'd5);
    do_write(A_CTRL, 32'h3, 4'b1111, 0, 0, OKAY);
    e0 = last_wr_edge;
    `CHECKEQ(irq_at_wr, 1'b0, "irq low after start")
    expect_irq_edge(e0 + 5);
    rd_expect(A_CTRL, 32'h2, OKAY);
    rd_expect(A_COUNT, 32'h0, OKAY);
    rd_expect(A_STATUS, 32'h1, OKAY);
    rises0 = irq_rises;
    do_write(A_STATUS, 32'h1, 4'b1111, 0, 0, OKAY);
    `CHECKEQ(irq_at_wr, 1'b0, "irq drops when EXPIRED is cleared")
    repeat (20) begin
      @(negedge aclk);
      `CHECK(!irq8, "no second interrupt after a one-shot")
    end
    rd_expect(A_STATUS, 32'h0, OKAY);
    `CHECK(irq_rises == rises0, "no second irq rise after a one-shot")

    // COUNT while counting, LOAD 40
    wr(A_LOAD, 32'd40);
    do_write(A_CTRL, 32'h3, 4'b1111, 0, 0, OKAY);
    e0 = last_wr_edge;
    `CHECKEQ(irq_at_wr, 1'b0, "irq low after start")
    do_read(A_COUNT, 0);
    exp_v = 32'd40 - (last_rd_edge - 1 - e0);
    `CHECKEQ(rd_data, exp_v, "COUNT while counting")
    do_read(A_COUNT, 2);
    exp_v = 32'd40 - (last_rd_edge - 1 - e0);
    `CHECKEQ(rd_data, exp_v, "COUNT while counting")
    expect_irq_edge(e0 + 40);
    rd_expect(A_CTRL, 32'h2, OKAY);
    do_write(A_STATUS, 32'h1, 4'b1111, 0, 0, OKAY);

    // LOAD 1
    wr(A_LOAD, 32'd1);
    do_write(A_CTRL, 32'h3, 4'b1111, 0, 0, OKAY);
    e0 = last_wr_edge;
    `CHECKEQ(irq_at_wr, 1'b0, "irq low on the start edge")
    expect_irq_edge(e0 + 1);
    rd_expect(A_CTRL, 32'h2, OKAY);
    do_write(A_STATUS, 32'h1, 4'b1111, 0, 0, OKAY);

    // LOAD 0 counts as 1
    wr(A_LOAD, 32'd0);
    do_write(A_CTRL, 32'h3, 4'b1111, 0, 0, OKAY);
    e0 = last_wr_edge;
    `CHECKEQ(irq_at_wr, 1'b0, "irq low on the start edge")
    expect_irq_edge(e0 + 1);
    rd_expect(A_COUNT, 32'h0, OKAY);
    rd_expect(A_CTRL, 32'h2, OKAY);
    do_write(A_STATUS, 32'h1, 4'b1111, 0, 0, OKAY);

    // ---------------- interrupt enable on a pending expiry ----------
    $display("--- IE on pending expiry");
    wr(A_LOAD, 32'd3);
    do_write(A_CTRL, 32'h1, 4'b1111, 0, 0, OKAY);   // EN, IE 0
    e0 = last_wr_edge;
    wait_until(e0 + 6);
    `CHECK(!irq8, "irq masked while IE is 0")
    rd_expect(A_STATUS, 32'h1, OKAY);
    do_write(A_STATUS, 32'h0, 4'b1111, 0, 0, OKAY);
    rd_expect(A_STATUS, 32'h1, OKAY);
    do_write(A_STATUS, 32'h1, 4'b1110, 0, 0, OKAY);
    rd_expect(A_STATUS, 32'h1, OKAY);
    do_write(A_CTRL, 32'h2, 4'b1111, 0, 0, OKAY);
    `CHECKEQ(irq_at_wr, 1'b1, "irq rises at once when IE is set on a pending expiry")
    do_write(A_CTRL, 32'h0, 4'b1111, 0, 0, OKAY);
    `CHECKEQ(irq_at_wr, 1'b0, "irq drops when IE is written 0")
    do_write(A_CTRL, 32'h2, 4'b1111, 0, 0, OKAY);
    `CHECKEQ(irq_at_wr, 1'b1, "irq rises again with IE")
    do_write(A_STATUS, 32'h1, 4'b1111, 0, 0, OKAY);
    `CHECKEQ(irq_at_wr, 1'b0, "irq drops on clear")
    rd_expect(A_STATUS, 32'h0, OKAY);

    // ---------------- periodic ----------------
    $display("--- periodic");
    wr(A_LOAD, 32'd10);
    do_write(A_CTRL, 32'h7, 4'b1111, 0, 0, OKAY);
    e0 = last_wr_edge;
    `CHECKEQ(irq_at_wr, 1'b0, "irq low after periodic start")
    for (k = 1; k <= 3; k = k + 1) begin
      expect_irq_edge(e0 + 10 * k);
      do_write(A_STATUS, 32'h1, 4'b1111, 0, 0, OKAY);
      `CHECKEQ(irq_at_wr, 1'b0, "periodic expiry cleared")
      if (k == 1) rd_expect(A_CTRL, 32'h7, OKAY);
    end
    wait_until(e0 + 39);
    do_write(A_STATUS, 32'h1, 4'b1111, 0, 0, OKAY);
    `CHECK(last_wr_edge == e0 + 40, "clear lands on the count-end edge")
    `CHECKEQ(irq_at_wr, 1'b1, "a count end beats a clear")
    `CHECK(irq8, "irq stays high after the colliding clear")
    rd_expect(A_STATUS, 32'h1, OKAY);
    do_write(A_CTRL, 32'h6, 4'b1111, 0, 0, OKAY);   // stop, keep IE and MODE
    rd_expect(A_CTRL, 32'h6, OKAY);
    do_write(A_STATUS, 32'h1, 4'b1111, 0, 0, OKAY);
    repeat (30) begin
      @(negedge aclk);
      `CHECK(!irq8, "no expiry after periodic stop")
    end
    rd_expect(A_STATUS, 32'h0, OKAY);

    // ---------------- stop freezes COUNT ----------------
    $display("--- stop freezes COUNT");
    wr(A_LOAD, 32'd100);
    do_write(A_CTRL, 32'h3, 4'b1111, 0, 0, OKAY);
    e0 = last_wr_edge;
    wait_until(e0 + 20);
    do_write(A_CTRL, 32'h2, 4'b1111, 0, 0, OKAY);
    e1 = last_wr_edge;
    frozen = 32'd100 - (e1 - e0);
    rd_expect(A_COUNT, frozen, OKAY);
    repeat (10) @(negedge aclk);
    rd_expect(A_COUNT, frozen, OKAY);
    rd_expect(A_CTRL, 32'h2, OKAY);
    wait_until(e0 + 130);
    `CHECK(!irq8, "a stopped count never ends")
    rd_expect(A_STATUS, 32'h0, OKAY);

    // ---------------- restart mid-count ----------------
    $display("--- restart");
    wr(A_LOAD, 32'd30);
    do_write(A_CTRL, 32'h3, 4'b1111, 0, 0, OKAY);
    e0 = last_wr_edge;
    wait_until(e0 + 10);
    do_write(A_CTRL, 32'h3, 4'b1111, 0, 0, OKAY);
    e1 = last_wr_edge;
    `CHECKEQ(irq_at_wr, 1'b0, "no expiry on a mid-count restart")
    expect_irq_edge(e1 + 30);
    rd_expect(A_CTRL, 32'h2, OKAY);
    do_write(A_STATUS, 32'h1, 4'b1111, 0, 0, OKAY);

    // restart landing on the count-end edge
    wr(A_LOAD, 32'd8);
    do_write(A_CTRL, 32'h3, 4'b1111, 0, 0, OKAY);
    e0 = last_wr_edge;
    wait_until(e0 + 7);
    do_write(A_CTRL, 32'h3, 4'b1111, 0, 0, OKAY);
    `CHECK(last_wr_edge == e0 + 8, "restart lands on the count-end edge")
    `CHECKEQ(irq_at_wr, 1'b1, "EXPIRED set by the count that ended")
    rd_expect(A_CTRL, 32'h3, OKAY);
    do_write(A_STATUS, 32'h1, 4'b1111, 0, 0, OKAY);
    `CHECKEQ(irq_at_wr, 1'b0, "clear after restart")
    expect_irq_edge(e0 + 16);
    rd_expect(A_CTRL, 32'h2, OKAY);
    do_write(A_STATUS, 32'h1, 4'b1111, 0, 0, OKAY);

    // stop landing on a periodic count-end edge
    wr(A_LOAD, 32'd6);
    do_write(A_CTRL, 32'h7, 4'b1111, 0, 0, OKAY);
    e0 = last_wr_edge;
    wait_until(e0 + 5);
    do_write(A_CTRL, 32'h6, 4'b1111, 0, 0, OKAY);
    `CHECK(last_wr_edge == e0 + 6, "stop lands on the count-end edge")
    `CHECKEQ(irq_at_wr, 1'b1, "EXPIRED set on the stopping edge")
    rd_expect(A_COUNT, 32'd6, OKAY);
    rd_expect(A_CTRL, 32'h6, OKAY);
    do_write(A_STATUS, 32'h1, 4'b1111, 0, 0, OKAY);
    repeat (10) begin
      @(negedge aclk);
      `CHECK(!irq8, "no expiry after a stop on the count end")
    end
    rd_expect(A_COUNT, 32'd6, OKAY);
    m_load = 32'd6;

    // ---------------- read and write on the same edge ----------------
    $display("--- read and write together");
    fork
      do_write(A_LOAD, 32'h0BADBEEF, 4'b1111, 0, 0, OKAY);
      do_read(A_LOAD, 1);
    join
    `CHECK(last_rd_edge == last_wr_edge, "read and write accepted on the same edge")
    `CHECKEQ(rd_data, m_load, "read on the write edge returns the old value")
    m_load = 32'h0BADBEEF;
    rd_expect(A_LOAD, m_load, OKAY);

    // ---------------- reset during traffic ----------------
    $display("--- reset during a count");
    wr(A_LOAD, 32'd50);
    do_write(A_CTRL, 32'h3, 4'b1111, 0, 0, OKAY);
    e0 = last_wr_edge;
    wait_until(e0 + 10);
    // leave a write address held
    `CHECK(awready8, "AWREADY high before the lone address")
    awaddr  = A_LOAD;
    awvalid = 1'b1;
    @(negedge aclk);
    awvalid = 1'b0;
    `CHECK(!awready8 && !bvalid8, "address held without data")
    apply_reset;
    `CHECK(awready8 && wready8 && arready8, "ready signals high after reset")
    `CHECK(!bvalid8 && !rvalid8 && !irq8, "outputs idle after reset")
    rd_expect(A_CTRL, 32'h0, OKAY);
    rd_expect(A_LOAD, 32'h0, OKAY);
    rd_expect(A_COUNT, 32'h0, OKAY);
    rd_expect(A_STATUS, 32'h0, OKAY);
    // W first: a stale held address would complete the write early
    do_write(A_LOAD, 32'h00000077, 4'b1111, 2, 0, OKAY);
    rd_expect(A_LOAD, 32'h77, OKAY);
    // pending B and R across reset
    `CHECK(awready8 && wready8 && arready8, "channels idle before pending responses")
    awaddr  = A_LOAD;
    wdata   = 32'h00001234;
    wstrb   = 4'b1111;
    awvalid = 1'b1;
    wvalid  = 1'b1;
    @(negedge aclk);
    awvalid = 1'b0;
    wvalid  = 1'b0;
    `CHECK(bvalid8, "write response pending")
    araddr  = A_LOAD;
    arvalid = 1'b1;
    @(negedge aclk);
    arvalid = 1'b0;
    `CHECK(rvalid8, "read response pending")
    `CHECKEQ(rdata8, 32'h00001234, "pending read data")
    apply_reset;
    `CHECK(!bvalid8 && !rvalid8, "reset drops BVALID and RVALID")
    rd_expect(A_LOAD, 32'h0, OKAY);
    wait_until(e0 + 70);
    `CHECK(!irq8, "no expiry after reset")
    rd_expect(A_STATUS, 32'h0, OKAY);
    rd_expect(A_CTRL, 32'h0, OKAY);

    // ---------------- offsets from 0x10 up at ADDR_WIDTH 8 ----------
    // The ADDR_WIDTH 4 instance legitimately aliases these; stop comparing.
    $display("--- unmapped offsets at ADDR_WIDTH 8");
    cmp_en = 1'b0;
    wr(A_LOAD, 32'd2);
    do_write(A_CTRL, 32'h1, 4'b1111, 0, 0, OKAY);
    e0 = last_wr_edge;
    wait_until(e0 + 4);
    rd_expect(A_STATUS, 32'h1, OKAY);
    wr(A_LOAD, 32'h00000077);
    wr(A_CTRL, 32'h4);
    do_write(8'h10, 32'h00000003, 4'b1111, 0, 0, SLVERR);
    `CHECKEQ(irq_at_wr, 1'b0, "0x10 does not alias CTRL")
    do_write(8'h14, 32'hFFFFFFFF, 4'b1111, 1, 0, SLVERR);
    do_write(8'h18, 32'h00000005, 4'b1111, 2, 0, SLVERR);
    do_write(8'h1C, 32'h00000001, 4'b1111, 0, 0, SLVERR);
    do_write(8'h40, 32'h00000003, 4'b1111, 0, 0, SLVERR);
    do_write(8'h84, 32'hFFFFFFFF, 4'b1111, 0, 0, SLVERR);
    do_write(8'hF4, 32'hFFFFFFFF, 4'b1111, 0, 0, SLVERR);
    do_write(8'hFC, 32'h00000001, 4'b1111, 0, 0, SLVERR);
    rd_expect(A_CTRL, 32'h4, OKAY);
    rd_expect(A_LOAD, 32'h77, OKAY);
    rd_expect(A_COUNT, 32'h0, OKAY);
    rd_expect(A_STATUS, 32'h1, OKAY);
    repeat (5) @(negedge aclk);
    rd_expect(A_COUNT, 32'h0, OKAY);
    `CHECK(!irq8, "no interrupt from unmapped writes")
    rd_expect(8'h10, 32'h0, SLVERR);
    rd_expect(8'h14, 32'h0, SLVERR);
    rd_expect(8'h18, 32'h0, SLVERR);
    rd_expect(8'h1C, 32'h0, SLVERR);
    rd_expect(8'h44, 32'h0, SLVERR);
    rd_expect(8'h80, 32'h0, SLVERR);
    rd_expect(8'hF0, 32'h0, SLVERR);
    rd_expect(8'hFC, 32'h0, SLVERR);

    // ---------------- verdict ----------------
    repeat (2) @(negedge aclk);
    `CHECK(cmp_fail == 0, "ADDR_WIDTH 4 and 8 instances agree on mapped traffic")
    `CHECK(mon_pass > 0, "channel monitor exercised under backpressure")
    passed = passed + mon_pass;
    failed = failed + mon_failed;
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

endmodule

`default_nettype wire
=== END FILE ===
